<template>
  <div class="deck-embed">
    <div class="deck-frame" ref="deckFrame">
      <iframe
        ref="deckIframe"
        src="https://www.henryw.me/CCGL9074/"
        title="Live scrollytelling deck built on the engine"
        loading="lazy"
      ></iframe>
    </div>
    <p class="deck-link">Cramped in the frame? <a href="https://www.henryw.me/CCGL9074/" target="_blank" rel="noopener">Open it fullscreen &nearr;</a></p>
  </div>
</template>

<script>
export default {
  name: 'LiveDeckEmbed',
  mounted() {
    this._onDeckResize = () => this.scaleDeck();
    window.addEventListener('resize', this._onDeckResize);
    this.$nextTick(() => this.scaleDeck());
  },
  unmounted() {
    if (this._onDeckResize) window.removeEventListener('resize', this._onDeckResize);
  },
  methods: {
    scaleDeck() {
      const frame = this.$refs.deckFrame;
      const iframe = this.$refs.deckIframe;
      if (!frame || !iframe) return;
      const DESIGN_W = 1200;
      const DESIGN_H = 750;
      const cw = frame.clientWidth;
      if (cw >= 460) {
        const scale = cw / DESIGN_W;
        iframe.style.width = `${DESIGN_W}px`;
        iframe.style.height = `${DESIGN_H}px`;
        iframe.style.transform = `scale(${scale})`;
        frame.style.height = `${Math.round(DESIGN_H * scale)}px`;
      } else {
        iframe.style.width = '100%';
        iframe.style.height = '';
        iframe.style.transform = 'none';
        frame.style.height = '';
      }
    },
  },
};
</script>

