<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import SectionMenu from './SectionMenu.vue';
import ChapterRail from './ChapterRail.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import SourceViewLinks from './ui/SourceViewLinks.vue';
import { projectEntries } from '../data/projects';

export default {
  name: 'ProjectsTab',
  components: { AiViewTerm, SourceViewLinks, SectionMenu, ChapterRail },
  mixins: [scrollRevealMixin],
  data() {
    return {
      expanded: { professional: true, coursework: true, personal: true },
      searchQuery: '',
      projectEntries,
      useMenu: false
    };
  },
  computed: {
    searchTerms() {
      return this.searchQuery
        .toLowerCase()
        .split(/[\s,.;:!?()[\]{}"']+/)
        .map((term) => term.trim())
        .filter((term) => term.length >= 2);
    },
    searchActive() {
      return this.searchTerms.length > 0;
    },
    hasSearchMatches() {
      return this.projectEntries.some((entry) => this.entryMatches(entry.id));
    },
    chapterItems() {
      return [
        { key: 'professional', id: 'projects-professional', label: 'Professional', title: 'Professional and lab work' },
        { key: 'coursework', id: 'projects-coursework', label: 'Coursework' },
        { key: 'personal', id: 'projects-personal', label: 'Personal', title: 'On my own time' }
      ].filter((item) => this.groupVisible(item.key));
    }
  },
  watch: {
    searchQuery() {
      this.refreshScrollReveal();
    }
  },
  mounted() {
    this.useMenu = this.matchMenu();
    this._menuMq = window.matchMedia('(min-width: 900px) and (hover: hover) and (pointer: fine)');
    this._onMenuMq = (e) => { this.useMenu = e.matches; };
    if (this._menuMq.addEventListener) this._menuMq.addEventListener('change', this._onMenuMq);
    // Group auto-expansion is disabled (groups are always expanded).
    // window.__expandEntryForLanding = (id) => this.ensureEntryExpanded(id);
    // Returning from a project page (e.g. /projects?to=dealtracker): expand the
    // entry's group so it renders, then let the central afterEach landing
    // smooth-scroll to it. The query is consumed so returning later (back from
    // another page) restores the saved scroll position instead of re-jumping.
    const to = this.$route.query.to;
    if (!to) return;
    const targetEntry = this.entryById(to);
    if (targetEntry) {
      this.expanded = {
        ...this.expanded,
        [targetEntry.group]: true
      };
    }
    this.$router.replace({ path: '/projects', query: {} });
  },
  unmounted() {
    if (this._menuMq && this._menuMq.removeEventListener) this._menuMq.removeEventListener('change', this._onMenuMq);
    // window.__expandEntryForLanding = null;
  },
  methods: {
    matchMenu() {
      return typeof window !== 'undefined'
        && window.matchMedia
        && window.matchMedia('(min-width: 900px) and (hover: hover) and (pointer: fine)').matches;
    },
    // ensureEntryExpanded(id) {
    //   const entry = this.entryById(id);
    //   if (!entry || !entry.group) return;
    //   if (!this.isGroupExpanded(entry.group)) {
    //     this.expanded = {
    //       ...this.expanded,
    //       [entry.group]: true
    //     };
    //   }
    // },
    escapeHtml(text) {
      return String(text == null ? '' : text)
        .split('&').join('&amp;')
        .split('<').join('&lt;')
        .split('>').join('&gt;')
        .split(String.fromCharCode(34)).join('&quot;')
        .split("'").join('&#39;');
    },
    escapeRegExp(text) {
      return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    },
    highlightText(text) {
      const escaped = this.escapeHtml(text);
      const terms = [...new Set(this.searchTerms)]
        .sort((a, b) => b.length - a.length)
        .map((term) => this.escapeRegExp(term));
      if (!terms.length) return escaped;

      const re = new RegExp(`(${terms.join('|')})`, 'gi');
      return escaped.replace(re, '<mark>$1</mark>');
    },
    entryById(id) {
      return this.projectEntries.find((entry) => entry.id === id);
    },
    entryMatches(id) {
      const entry = this.entryById(id);
      if (!entry) return false;
      const text = [
        entry.title,
        entry.subtitle,
        entry.summary,
        ...(entry.details || []),
        entry.text
      ].join(' ').toLowerCase();
      return this.searchTerms.every((term) => text.includes(term));
    },
    groupMatches(groupKey) {
      return this.projectEntries
        .filter((entry) => entry.group === groupKey)
        .some((entry) => this.entryMatches(entry.id));
    },
    groupCount(groupKey) {
      return this.projectEntries
        .filter((entry) => entry.group === groupKey && this.entryMatches(entry.id))
        .length;
    },
    groupVisible(groupKey) {
      if (!this.searchActive) return true;
      return this.groupMatches(groupKey);
    },
    isGroupExpanded(groupKey) {
      if (this.searchActive) return this.groupMatches(groupKey);
      return this.expanded[groupKey];
    },
    entryVisible(id) {
      if (!this.searchActive) return true;
      return this.entryMatches(id);
    },
    // Toggle disabled: groups stay expanded.
    // toggleGroup(groupKey) {
